// Evidence helpers shared by the web manual-JSON validator and the
// process-receipt-imports Edge Function. The Edge copy is generated by
// scripts/sync-edge-domain.mjs, so this file may import only from ./money.
import { roundMoney, roundQty, roundUnitPrice } from './money.ts';

export type AccountingLine = {
  product_name: string;
  qty: number;
  unit_price_orig: number;
  discount_orig?: number | undefined;
};

export type MultiBuyLine = {
  qty: number;
  unit_price_orig: number;
  discount_orig?: number | null | undefined;
  raw_text?: string | undefined;
  row_kind?: string | undefined;
  qty_evidence?: string | undefined;
  printed_line_total_orig?: number | null | undefined;
};

type PairPass = 'cancellation' | 'discount';

const INVISIBLE_CHARS = /[\u200B-\u200D\uFEFF]/g;
const PHYSICAL_LINE_BREAK = /\s*(?:\/|\||\r?\n)\s*/u;

export function normalizeReceiptText(value: string): string {
  return value
    .normalize('NFKC')
    .replace(INVISIBLE_CHARS, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

export function amountAppearsInText(text: string, amount: number): boolean {
  const absolute = Math.abs(roundMoney(amount)).toFixed(2);
  const variants = [absolute, absolute.replace('.', ',')];
  const compactText = text.replace(/\s/g, '');
  return variants.some((variant) => compactText.includes(variant));
}

function amountPositions(text: string, amount: number): number[] {
  const absolute = Math.abs(roundMoney(amount)).toFixed(2);
  const compactText = text.replace(/\s/g, '');
  return [absolute, absolute.replace('.', ',')]
    .flatMap((variant) => [compactText.indexOf(variant), compactText.lastIndexOf(variant)])
    .filter((position) => position >= 0);
}

export function integerAppearsInText(text: string, value: number): boolean {
  return new RegExp(String.raw`(?:^|\D)${String(value)}(?:\D|$)`, 'u').test(text);
}

export function hasExplicitMultiplier(text: string, qty: number): boolean {
  const rawQty = String(roundQty(qty)).replace('.', '[.,]');
  const quantityPattern = new RegExp(
    String.raw`(?:^|\s)(?:${rawQty}\s*(?:x|×|stk\.?|st\.?|pcs)|(?:x|×)\s*${rawQty})(?:\s|$)`,
    'iu',
  );
  return quantityPattern.test(text);
}

// Fuel pumps print the unit as `L'ter`, `Liter` or `Ltr`; the apostrophe survives
// OCR in several shapes.
export function hasWeightOrVolume(text: string): boolean {
  return /(?:^|\s)\d+(?:[.,]\d+)?\s*(?:kg|g|ml|l(?:i?ter|['’´`]ter|tr)?)(?:\s|$)/iu.test(text);
}

/**
 * Stores such as Aldi print `N x unit  total` where the shelf price makes
 * `N * unit` differ from the charged `total` (a multi-buy price). The printed
 * total is authoritative, so the gap becomes a per-unit discount, but only when
 * the row text itself shows the multiplier, the unit price and the total on one
 * physical line and the resulting line reproduces the printed total exactly. A
 * multiplier on a separate line belongs to a neighbouring row (EDEKA layout) and
 * is repaired by reassociateMisattachedMultiplier instead.
 */
export function applyMultiBuyPrice<T extends MultiBuyLine>(item: T): T {
  const printedTotal = item.printed_line_total_orig;
  if (
    item.row_kind !== 'item' ||
    item.qty_evidence !== 'explicit_multiplier' ||
    !Number.isInteger(item.qty) ||
    item.qty < 2 ||
    (item.discount_orig ?? 0) !== 0 ||
    item.unit_price_orig <= 0 ||
    printedTotal == null ||
    printedTotal <= 0 ||
    !item.raw_text
  ) {
    return item;
  }
  const shelfTotal = roundMoney(item.qty * item.unit_price_orig);
  const chargedTotal = roundMoney(printedTotal);
  if (shelfTotal - chargedTotal <= 0.02) return item;
  if (PHYSICAL_LINE_BREAK.test(item.raw_text)) return item;
  if (
    !hasExplicitMultiplier(item.raw_text, item.qty) ||
    !amountAppearsInText(item.raw_text, item.unit_price_orig) ||
    !amountAppearsInText(item.raw_text, chargedTotal)
  ) {
    return item;
  }
  // `N x unit  total` reads multiplier first; `total ... N x unit` is how a
  // multiplier printed for the next product looks, so it stays untouched.
  const unitPosition = Math.min(...amountPositions(item.raw_text, item.unit_price_orig));
  const totalPosition = Math.max(...amountPositions(item.raw_text, chargedTotal));
  if (unitPosition >= totalPosition) return item;
  const discount = roundUnitPrice((shelfTotal - chargedTotal) / item.qty);
  if (roundMoney(item.qty * (item.unit_price_orig - discount)) !== chargedTotal) return item;
  return { ...item, discount_orig: discount };
}

/** Cancellation pairs first, then partial discounts; returns a new array. */
export function mergeAccountingPairs<T extends AccountingLine>(items: T[]): T[] {
  const result = items.map((item) => ({ ...item }));
  const removed = new Set<number>();
  const groups = groupItemIndices(result);

  for (const indices of groups.values()) {
    const positives = indices.filter((index) => isSignedPrice(result[index], 1));
    const negatives = indices.filter((index) => isSignedPrice(result[index], -1));
    const claimed = new Set<number>();

    // Exact cancellations must claim first; otherwise a cancellation could be
    // consumed as a partial discount. Both passes share the same claimed set.
    claimPairPass(result, positives, negatives, claimed, removed, 'cancellation');
    claimPairPass(result, positives, negatives, claimed, removed, 'discount');
  }
  return result.filter((_, index) => !removed.has(index));
}

function groupItemIndices(items: AccountingLine[]): Map<string, number[]> {
  const groups = new Map<string, number[]>();
  items.forEach((item, index) => {
    const key = normalizeReceiptText(item.product_name);
    if (!key) return;
    const indices = groups.get(key);
    if (indices) indices.push(index);
    else groups.set(key, [index]);
  });
  return groups;
}

function claimPairPass(
  items: AccountingLine[],
  positiveIndices: number[],
  negativeIndices: number[],
  claimed: Set<number>,
  removed: Set<number>,
  pass: PairPass,
): void {
  for (const negativeIndex of negativeIndices) {
    if (claimed.has(negativeIndex)) continue;
    const negative = items[negativeIndex];
    if (!negative) continue;
    const positiveIndex = positiveIndices.find((candidateIndex) =>
      isPairCandidate(items[candidateIndex], negative, claimed.has(candidateIndex), pass),
    );
    if (positiveIndex === undefined) continue;
    const positive = items[positiveIndex];
    if (!positive) continue;

    claimed.add(positiveIndex);
    claimed.add(negativeIndex);
    removed.add(negativeIndex);
    if (pass === 'cancellation') {
      positive.unit_price_orig = 0;
      positive.discount_orig = 0;
    } else {
      positive.discount_orig = roundMoney(Math.abs(negative.unit_price_orig));
    }
  }
}

function isPairCandidate(
  positive: AccountingLine | undefined,
  negative: AccountingLine,
  alreadyClaimed: boolean,
  pass: PairPass,
): boolean {
  if (!positive || alreadyClaimed || Math.abs(positive.qty - negative.qty) > 0.001) return false;
  const positiveTotal = grossLineTotal(positive);
  const negativeTotal = grossLineTotal(negative);
  return pass === 'cancellation' ? positiveTotal === negativeTotal : positiveTotal > negativeTotal;
}

function grossLineTotal(item: AccountingLine): number {
  return roundMoney(Math.abs(item.qty * item.unit_price_orig));
}

function isSignedPrice(item: AccountingLine | undefined, sign: 1 | -1): boolean {
  return sign * (item?.unit_price_orig ?? 0) > 0;
}
